const E=Engine,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const numberFormatter=new Intl.NumberFormat('en-IN',{maximumFractionDigits:0});
const money=n=>n===null||n===undefined?'—':numberFormatter.format(n),num=money,pct=n=>n===null||n===undefined?'—':(n*100).toFixed(1)+'%',compact=n=>n==null?'—':Math.abs(n)>=1e7?(n/1e7).toFixed(2)+' Cr':Math.abs(n)>=1e5?(n/1e5).toFixed(2)+' L':Math.abs(n)>=1000?(n/1000).toFixed(1)+'K':money(n);
const formatDate=s=>s?new Date(s+'T12:00:00Z').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}):'—';
const views=[['overview','◫','Top Line Performance','Top Line Performance','A connected view of demand, deliveries and commercial performance.'],['trends','⌁','Daily & monthly trends','See the momentum.','Event-date trends with explicit visibility of missing report days.'],['kam','◎','KAM performance','Ownership. Accountability. Growth.','Compare account managers across demand, deliveries and portfolio contribution.'],['kamseller','⇄','KAM × Seller','Every portfolio, unpacked.','A two-level scorecard connecting account managers to their shop accounts.'],['seller','▤','Seller intelligence','The partners driving performance.','Shop account rankings, concentration and a route into product detail.'],['sku','▦','SKU intelligence','Find the products that matter.','Product-level value, volume, pricing and contribution.'],['brand','◇','Brand performance','A clearer view of brand demand.','Brand contribution and selling productivity across the marketplace.'],['category','◈','Category explorer','Explore every category layer.','Five source category levels, preserved without assuming a clean hierarchy.'],['operations','↗','Order & fulfilment','From demand to delivery.','Order states, shipping partners, payment mix and delivery lead times.'],['economics','◉','Commercial economics','Understand the quality of revenue.','Merchandise value, source commission and purchase-cost contribution.'],['data','＋','Data & daily uploads','Two files. One daily ritual.','Drop in your daily reports. Metrics, rankings and history update automatically.'],['guide','?','Guide & definitions','Built for the leadership conversation.','A guided walkthrough, metric dictionary and reporting methodology.']];
