let db,data,filtered=[],previous=[],currentView='overview',filters={},from='',to='',compare='previous',page=0,search='',sortKey='gmv',sortDir=-1,categoryLevel='cat1',trendMetric='value',trendGrain='day',tableRows=[],tableDims=[],staged=null,walkStep=0,persisted=false;
let topCalendar={year:'',month:''};
let target=0;try{target=Number(localStorage.getItem('othoba-target')||0)}catch{}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200)}
function openDB(){return new Promise((res,rej)=>{const req=indexedDB.open('othoba-performance-clean-20261030-blue-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('state');req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)})}
function getDB(){return new Promise((res,rej)=>{let q=db.transaction('state').objectStore('state').get('dataset');q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)})}
function saveDB(value){return new Promise((res,rej)=>{let t=db.transaction('state','readwrite');t.objectStore('state').put(value.store?Packed.plain(value):value,'dataset');t.oncomplete=res;t.onerror=()=>rej(t.error);t.onabort=()=>rej(t.error)})}
async function commitData(next){if(!db)throw Error('Browser storage unavailable. Export a backup and use a browser with IndexedDB enabled.');next.updatedAt=new Date().toISOString();await saveDB(next);data=Packed.state(await backgroundTask('load',{payload:next.store?Packed.plain(next):next}));queryResults.clear();preparedTables=new WeakMap();persisted=true;updateSaved();}
function updateSaved(){$('#savedState').textContent=persisted?'● Saved in this browser':'● Attached baseline';}
function showModal(title,body){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;enhanceTables($('#modalBody'));if(!$('#modal').open)$('#modal').showModal();}
function badge(s,color=''){return `<span class="pill ${color}">${esc(s)}</span>`}
function panel(title,sub,body,extra=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2><div class="caption">${sub}</div></div>${extra}</div><div class="panel-body">${body}</div></section>`}
function matchesFilters(r){return Object.entries(filters).every(([k,v])=>!v||(k==='categoryAny'?[1,2,3,4,5].some(i=>(r['cat'+i]||'Unmapped')===v):(r[k]||'Unmapped')===v));}
function rangeRows(a,b){return data.store.select(a,b,filters);}
function coverageFor(stream,a,b){let have=0;for(const day of data.store.coverage[stream])if(day>=a&&day<=b)have++;let total=Math.round((new Date(b)-new Date(a))/864e5)+1;return {have,total};}
function hasCoverage(stream,a,b){return coverageFor(stream,a,b).have>0;}
function delta(value,key,stream){if(compare==='none')return 'Comparison off';let [a,b]=E.comparison(from,to,compare),pc=coverageFor(stream,a,b),cc=coverageFor(stream,from,to);if(!pc.have)return `<span class="delta neutral">No comparison data</span>`;if(pc.have<pc.total||cc.have<cc.total)return `<span class="delta neutral">Partial coverage</span>`;let prev=E.aggregate(previous)[key];if(!prev)return `<span class="delta neutral">${value?'New activity':'No change'}</span>`;let v=value/prev-1;return `<span class="delta ${v>0?'positive':v<0?'negative':''}">${TargetEngine.signed(v)}</span><span>vs comparison</span>`;}
function kpi(label,value,foot,key,stream='gross',hero=false,asMoney=false){return `<div class="kpi ${hero?'hero':''}"><div class="kpi-label">${label}<span>${stream==='net'?'↳':'↗'}</span></div><div class="kpi-value">${asMoney?'<span class="currency">৳</span>':''}${esc(value)}</div><div class="kpi-bottom">${key?delta(E.aggregate(filtered)[key],key,stream):''}${foot?'<span>'+foot+'</span>':''}</div></div>`;}
function primaryKPIs(rows=filtered,mini=false){const a=E.aggregate(rows),g=hasCoverage('gross',from,to),n=hasCoverage('net',from,to);return `<div class="kpis">${kpi('GMV · Gross merchandise value',g?compact(a.gmv):'—','',mini?'': 'gmv','gross',true,true)}${kpi('GOS · Gross suborders',g?num(a.gos):'—','Distinct suborder IDs',mini?'':'gos')}${kpi('NMV · Delivered merchandise value',n?compact(a.nmv):'—','',mini?'':'nmv','net',false,true)}${kpi('NOS · Delivered suborders',n?num(a.nos):'—','Distinct suborder IDs',mini?'':'nos','net')}</div>`;}
function bars(rows,dim,metric='gmv',limit=6){const groups=E.group(rows,[dim]).sort((a,b)=>b[metric]-a[metric]).filter(x=>x[metric]!==0).slice(0,limit),max=Math.max(...groups.map(x=>x[metric]),1),total=E.aggregate(rows)[metric];if(!groups.length)return '<div class="empty">No activity for this selection</div>';return `<div class="bars">${groups.map(x=>`<div class="bar-row clickable" data-drill="${dim}" data-val="${esc(x.labels[0])}" tabindex="0" role="button"><div class="bar-label" title="${esc(x.labels[0])}">${esc(x.labels[0])}</div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,x[metric]/max*100)}%;${metric==='nmv'?'background:#6e8395':''}"></div></div><div class="bar-value">${compact(x[metric])} <span class="thin">${pct(total?x[metric]/total:0)}</span></div></div>`).join('')}</div>`;}
function mini(label,value,detail=''){return `<div class="mini-stat"><span>${label}</span><strong>${value}</strong>${detail?`<p class="thin">${detail}</p>`:''}</div>`;}
function trendChart(){const dates=E.dateRange(from,to),key=trendMetric==='value'?['gmv','nmv']:trendMetric==='orders'?['gos','nos']:['gis','nis'];const byDate=new Map((activeResult?.trend||[]).map(x=>[x.date,x]));let buckets=new Map;for(const date of dates){let k=trendGrain==='month'?date.slice(0,7):date;if(!buckets.has(k))buckets.set(k,[]);buckets.get(k).push(date);}const monthly=trendGrain==='month'?new Map(E.group(filtered,['month']).map(x=>[x.labels[0],x])):null;let b=[...buckets].map(([date,ds])=>{const a=monthly?monthly.get(date):byDate.get(date);return {date,g:a?.[key[0]]||0,n:a?.[key[1]]||0,gOK:ds.some(d=>data.store.coverage.gross.has(d)),nOK:ds.some(d=>data.store.coverage.net.has(d)),ds};});
if(!b.length)return '<div class="empty">Select a date range</div>';const W=850,H=220,L=54,R=17,T=15,B=37,max=Math.max(...b.flatMap(x=>[x.g,x.n]),1),cw=(W-L-R)/b.length,bw=Math.min(28,cw*.29);let s=`<svg class="trend-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Gross and delivered event trend">`;for(let i=0;i<=4;i++){let y=T+(H-T-B)*i/4;s+=`<line x1="${L}" x2="${W-R}" y1="${y}" y2="${y}" stroke="#e9eee5" stroke-dasharray="3 5"/><text x="${L-10}" y="${y+3}" text-anchor="end">${compact(max*(1-i/4))}</text>`;}
b.forEach((x,i)=>{let cx=L+cw*(i+.5),hh=H-T-B;for(const [j,k,ok]of [[0,'g','gOK'],[1,'n','nOK']]){if(x[ok]){let bh=x[k]/max*hh;s+=`<rect x="${cx+(j?2:-bw-2)}" y="${T+hh-bh}" width="${bw}" height="${Math.max(bh,1)}" rx="2" fill="${j?'#6e8395':'#439ddf'}"><title>${esc(x.date)} · ${j?'Delivered':'Gross'}: ${money(x[k])}</title></rect>`;}else{s+=`<text x="${cx+(j?bw/2+2:-bw/2-2)}" y="${T+hh-3}" text-anchor="middle">·</text>`;}}
if(b.length<=12||i%Math.ceil(b.length/9)===0)s+=`<text x="${cx}" y="${H-13}" text-anchor="middle">${trendGrain==='month'?esc(x.date):new Date(x.date+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'})}</text>`;});s+='</svg>';return s+`<div class="trend-note">${b.length===1?'One reporting day loaded. Add daily files to build the trend.':'Dots indicate missing report dates; missing values are not plotted as zero.'} ${trendGrain==='month'?'Monthly bars show only loaded days.':''}</div>`;}
function overview(){let a=E.aggregate(filtered),ss=E.group(filtered,['seller']).sort((a,b)=>b.gmv-a.gmv),ks=E.group(filtered,['kam']).sort((a,b)=>b.gmv-a.gmv),top=ss[0];let note=top&&a.gmv?`${esc(top.labels[0])} contributes ${pct(top.gmv/a.gmv)} of gross value; the top 5 sellers contribute ${pct(ss.slice(0,5).reduce((s,x)=>s+x.gmv,0)/a.gmv)}.`:'Load gross reports to surface seller concentration.';return primaryKPIs()+`<div class="insight-strip"><div class="insight-number">↗</div><div><strong>Leadership lens · Portfolio concentration</strong><p>${note} ${ks[0]&&a.gmv?'Leading KAM: '+esc(ks[0].labels[0])+' ('+pct(ks[0].gmv/a.gmv)+' of GMV).':''}</p></div></div><div class="grid-two">${panel('Demand & delivery pulse','Gross by order date · Delivered by delivery date',trendChart(),'<div class="legend"><span><i style="background:#439ddf"></i>Gross</span><span><i style="background:#6e8395"></i>Delivered</span></div>')}${panel('KAM contribution','Gross merchandise value · Click an owner to drill down',bars(filtered,'kam'))}</div><div class="mini-stats">${mini('Gross items sold · GIS',num(a.gis),'Delivered items: '+num(a.nis))}${mini('Gross average order value','৳ '+money(a.aov),'GMV ÷ distinct gross suborders')}${mini('Transacting sellers / SKUs',num(a.sellers)+' / '+num(a.skus),'Observed activity in gross reports')}</div><div class="grid-equal">${panel('Top shop accounts','Ranked by gross merchandise value',bars(filtered,'seller'))}${panel('Category contribution','Source Category 1 · Unmapped values stay visible',bars(filtered,'cat1'))}</div>${quickTable('Commercial ownership snapshot',['kam'],6)}`;}
function metricsOptions(){return `<div class="metric-switch">${[['value','Value'],['orders','Orders'],['units','Items']].map(([k,l])=>`<button data-trendmetric="${k}" class="${trendMetric===k?'active':''}">${l}</button>`).join('')}</div>`;}
function trends(){let a=E.aggregate(filtered);return primaryKPIs()+panel('Gross & delivered event trend','Missing days remain gaps; totals reflect only uploaded dates.',trendChart(),`<div class="table-tools"><select id="trendGrain"><option value="day" ${trendGrain==='day'?'selected':''}>Daily</option><option value="month" ${trendGrain==='month'?'selected':''}>Monthly</option></select>${metricsOptions()}</div>`)+quickTable(trendGrain==='day'?'Daily scorecard':'Monthly scorecard',[trendGrain==='day'?'date':'month'],100);}
const cols=[['gmv','GMV · ৳','money'],['gos','GOS','num'],['gis','GIS','num'],['nmv','NMV · ৳','money'],['nos','NOS','num'],['nis','Delivered items','num'],['share','GMV share','pct'],['aov','Gross AOV · ৳','money'],['nmargin','Delivered margin','pct'],['gcommission','Gross commission · ৳','money']];
function prepareTable(ds){let cache=preparedTables.get(filtered);if(!cache){cache=new Map();preparedTables.set(filtered,cache);}let key=ds.join('|');if(cache.has(key))return cache.get(key);let total=E.aggregate(filtered),result=E.group(filtered,ds).map(x=>({...x,share:total.gmv?x.gmv/total.gmv:null,nmargin:x.nmv?(x.nmv-x.ncost)/x.nmv:null}));cache.set(key,result);return result;}
function tableHTML(groups,ds,{full=true,limit=25}={}){let q=search.toLowerCase();let list=groups.filter(x=>x.labels.join(' ').toLowerCase().includes(q)).sort((a,b)=>{let aa=sortKey.startsWith('label')?a.labels[Number(sortKey.slice(5))||0]:a[sortKey],bb=sortKey.startsWith('label')?b.labels[Number(sortKey.slice(5))||0]:b[sortKey];if(aa===null||aa===undefined)return 1;if(bb===null||bb===undefined)return-1;return(typeof aa==='string'?aa.localeCompare(bb):aa-bb)*sortDir;});let start=full?page*limit:0;if(start>=list.length){page=0;start=0;}const shown=list.slice(start,start+limit),labelNames={kam:'KAM',seller:'Shop account',sku:'SKU / Product',brand:'Brand',cat1:'Category 1',cat2:'Category 2',cat3:'Category 3',cat4:'Category 4',cat5:'Category 5',date:'Event date',month:'Event month',status:'Order status',partner:'Shipping partner',payment:'Payment method',group:'Account group type',reason:'Cancel reason'};let html=`<div class="table-wrap"><table data-scorecard="true"><thead><tr>${ds.map((d,i)=>`<th data-sort="label${i}" style="text-align:left">${labelNames[d]||esc(d)} ${sortKey==='label'+i?'↕':''}</th>`).join('')}${cols.map(([k,l])=>`<th data-sort="${k}">${l} ${sortKey===k?(sortDir<0?'↓':'↑'):''}</th>`).join('')}</tr></thead><tbody>`;
html+=shown.map((x,i)=>`<tr class="drill" data-tableindex="${groups.indexOf(x)}">${x.labels.map((l,j)=>`<td class="label" title="${esc(l)}">${j===0?`<span class="rank">${String(start+i+1).padStart(2,'0')}</span>`:''}${esc(l)}${ds[j]==='sku'?`<small>${esc(x.rows[0].name).slice(0,100)}</small>`:''}</td>`).join('')}${cols.map(([k,l,t])=>`<td ${k==='share'?`class="heat" style="--w:${Math.min(100,(x[k]||0)*100)}%"`:''}>${t==='pct'?pct(x[k]):money(x[k])}</td>`).join('')}</tr>`).join('');if(!shown.length)html+=`<tr><td colspan="${ds.length+cols.length}"><div class="empty"><b>No matching activity</b>Adjust filters or upload reports for this period.</div></td></tr>`;html+='</tbody></table></div>';if(full)html+=`<div class="table-bottom"><span>${list.length?start+1:0}–${Math.min(start+limit,list.length)} of ${num(list.length)} groups · Click a row for detail</span><div class="pagination"><button id="prevPage" ${page===0?'disabled':''}>←</button><button id="nextPage" ${start+limit>=list.length?'disabled':''}>→</button></div></div>`;tableRows=groups;tableDims=ds;return html;}
function quickTable(title,ds,limit){let groups=prepareTable(ds);return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2><div class="caption">Both event streams in one scorecard · Values in BDT</div></div></div>${tableHTML(groups,ds,{full:false,limit})}</section>`;}
function dimensionPage(ds,title){const a=E.aggregate(filtered),groups=prepareTable(ds),top=[...groups].sort((a,b)=>b.gmv-a.gmv)[0];return primaryKPIs()+`<div class="mini-stats">${mini('Groups in selected period',num(groups.length),'Includes both gross and delivered activity')}${mini('Leading gross contributor',top?esc(top.labels.join(' / ')):'—',top?'৳ '+money(top.gmv)+' · '+pct(a.gmv?top.gmv/a.gmv:0)+' of GMV':'')}${mini('Gross transacting sellers',num(a.sellers),'Delivered transacting sellers: '+num(a.netSellers))}</div>`+(currentView==='category'?`<div class="notice">Category columns contain source taxonomy inconsistencies and blank levels. Select any source level below; no inferred category hierarchy is applied.</div>`:'')+`<section class="panel"><div class="panel-head"><div><h2>${title}</h2><div class="caption">Sortable scorecard · Distinct suborders at each grouping · Click a row to explore</div></div><div class="table-tools">${currentView==='category'?`<select id="categoryLevel">${[1,2,3,4,5].map(i=>`<option value="cat${i}" ${categoryLevel==='cat'+i?'selected':''}>Category ${i}</option>`).join('')}</select>`:''}<input id="tableSearch" placeholder="Search this view…" value="${esc(search)}" aria-label="Search table"></div></div><div id="tableContainer">${tableHTML(groups,ds)}</div></section><div class="thin">Suborders spanning multiple groups count once in each group; order counts across rows may not add to the platform total. Delivered margin = (NMV − delivered purchase cost) ÷ NMV.</div>`;}
function breakdownTable(rows,dim,stream){const groups=E.group(rows,[dim]).filter(x=>stream==='gross'?x.gos>0:x.nos>0).sort((a,b)=>b[stream==='gross'?'gmv':'nmv']-a[stream==='gross'?'gmv':'nmv']);return `<div class="table-wrap"><table><thead><tr><th>${esc(dim)}</th><th>${stream==='gross'?'GMV':'NMV'} · ৳</th><th>Suborders</th><th>Items</th></tr></thead><tbody>${groups.map(x=>`<tr><td class="label">${esc(x.labels[0])}</td><td>${money(stream==='gross'?x.gmv:x.nmv)}</td><td>${num(stream==='gross'?x.gos:x.nos)}</td><td>${num(stream==='gross'?x.gis:x.nis)}</td></tr>`).join('')}</tbody></table></div>`;}
function leads(rows){let m=new Map;for(const r of rows.filter(r=>r.stream==='net')){if(!m.has(r.id))m.set(r.id,{o:r.ordered,d:r.delivered});let x=m.get(r.id);if(r.ordered<x.o)x.o=r.ordered;if(r.delivered>x.d)x.d=r.delivered;}return [...m.values()].map(x=>(new Date(x.d)-new Date(x.o))/864e5).filter(x=>Number.isFinite(x)&&x>=0).sort((a,b)=>a-b);}
function cancelReasonTable(){let groups=activeResult.extra.cancelReasons||[];return '<div class="table-wrap"><table><thead><tr><th>Cancel reason</th><th>GMV · ৳</th><th>Suborders</th><th>Items</th></tr></thead><tbody>'+groups.map(x=>'<tr><td class="label">'+esc(x.labels[0])+'</td><td>'+money(x.gmv)+'</td><td>'+num(x.gos)+'</td><td>'+num(x.gis)+'</td></tr>').join('')+'</tbody></table></div>';}
function operations(){let a=E.aggregate(filtered),avg=activeResult.extra.leadAvg,med=activeResult.extra.leadMedian,closed=activeResult.extra.closed;return `<div class="notice">Gross statuses are the state captured when that report was exported. Later delivery files add delivery events; they do not rewrite old gross snapshots. The delivered/gross ratio for a day is not a cohort fulfilment rate.</div><div class="kpis">${kpi('Cancelled gross value','৳ '+compact(a.cancelGMV),'Gross snapshot · '+pct(a.cancelRate))}${kpi('Fully delivered gross suborders',num(closed),pct(a.gos?closed/a.gos:0)+' of gross suborders at export')}${kpi('Avg delivery lead time',avg===null?'—':avg.toFixed(1)+' days','Delivered suborders with valid timestamps','', 'net')}${kpi('Median delivery lead time',med===null?'—':med.toFixed(1)+' days',num(activeResult.extra.leadCount)+' delivered suborders measured','', 'net')}</div><div class="grid-equal">${panel('Gross order states','Source snapshot · State counts may overlap for mixed-state suborders',breakdownTable(filtered,'status','gross'))}${panel('Delivered shipping partners','Completed delivery events · Source partner names',bars(filtered,'partner','nmv',10))}</div><div class="grid-equal">${panel('Cancellation reasons','Cancelled rows from gross reports only',cancelReasonTable())}${panel('Gross payment mix','Merchandise value by payment method',bars(filtered,'payment','gmv',10))}</div>`;}
function economics(){let a=E.aggregate(filtered),retailDiscount=activeResult.extra.discount;return `<div class="notice">GMV and NMV use line-level TotalSellingPrice. These are merchandise values before order-level coupon/bank discounts and exclude shipping. Purchase-cost contribution excludes logistics, payments, subsidies, returns and overhead; it is not company profit. Delivered events are not adjusted for subsequent returns absent a returns feed.</div><div class="kpis">${kpi('Delivered purchase contribution','৳ '+compact(a.nmv-a.ncost),'NMV − delivered purchase cost','','net',true)}${kpi('Delivered merchandise margin',pct(a.margin),'Contribution ÷ NMV','','net')}${kpi('Gross source commission','৳ '+compact(a.gcommission),pct(a.takeRate)+' of GMV')}${kpi('Delivered source commission','৳ '+compact(a.ncommission),'Source Commission column','','net')}</div><div class="grid-equal">${panel('Merchandise economics bridge','Source values summed once per item line',`<div class="quality-list">${[['Gross merchandise value',a.gmv],['Gross purchase cost',a.gcost],['Gross purchase contribution',a.gmv-a.gcost],['Delivered merchandise value',a.nmv],['Delivered purchase cost',a.ncost],['Delivered purchase contribution',a.nmv-a.ncost],['Gross MRP markdown exposure',retailDiscount]].map(([l,v])=>`<div><span>${l}</span><b>৳ ${money(v)}</b></div>`).join('')}</div><p class="thin" style="margin-top:20px">Markdown exposure is Σ max(0, RegularPrice × Quantity − TotalSellingPrice). Commission is shown independently and is not added to purchase contribution.</p>`)}${panel('Account group contribution','Gross value · Internal and external group types',bars(filtered,'group','gmv',10))}</div>${targetPanel()}${quickTable('KAM commercial scorecard',['kam'],30)}`;}
function targetPanel(){let same=from.slice(0,7)===to.slice(0,7),month=from.slice(0,7),mr=data.store.select(month+'-01',month+'-31',{...filters,stream:'gross'}),actual=E.aggregate(mr).gmv,cov=new Set(mr.map(r=>r.date)).size;return `<section class="target-box"><h2>Monthly GMV target · ${esc(month)}</h2><p>Optional planning input. Target applies to the currently filtered portfolio; actuals include all loaded gross dates in this month.</p><div class="upload-controls"><label>Target · ৳ <input id="targetValue" type="number" min="0" value="${target||''}" placeholder="Enter target"></label><button id="saveTarget">Save target</button></div>${same&&target>0?`<div class="big">${pct(actual/target)} attained</div><p>৳ ${money(actual)} loaded actuals · ৳ ${money(Math.max(0,target-actual))} remaining · ${cov} observed report days</p><div class="progress"><div style="width:${Math.max(0,Math.min(100,actual/target*100))}%"></div></div>`:'<p>Select dates within one month and set a target to see attainment. Partial uploads are not extrapolated.</p>'}</section>`;}
function quality(){return activeResult.extra.quality||[];}
function dataPage(){const historyDates=data.store.dates;return `${folderCleanupPanel()}<section class="panel history-vault"><div class="panel-head"><div><h2>Your saved reporting history</h2><div class="caption">Every imported date is retained in this browser. The full HTML export embeds all history, including dates outside your current filters.</div></div></div><div class="panel-body"><div class="mini-stats">${mini('History coverage',formatDate(historyDates[0])+' – '+formatDate(historyDates.at(-1)))}${mini('Reporting days / Item records',num(historyDates.length)+' / '+num(data.rows.length))}${mini('Imported source files',num(data.imports.length),'Duplicate files are skipped')}</div><p><b>Daily sharing:</b> Upload today’s two reports, then select <b>Export full HTML</b>. Send the downloaded HTML to your boss. It opens with all included data, views and filters ready to use; no CSV uploads or internet connection are required.</p><p class="thin">Keep using the same browser to retain your working history. Export the updated HTML after each daily import as a portable backup. Browser cache removal does not change previously downloaded HTML copies.</p></div></section><div class="grid-two">${panel('Daily import desk','CSV uploads · Multiple days supported · No dependency on external services',`<div class="upload-zone" id="dropZone" role="button" tabindex="0"><span style="font-size:29px;color:var(--green)">↥</span><h3>Drop your two daily CSV reports here</h3><p>Gross sales report + Delivered sales report<br>Choose multiple files to backfill previous days.</p><button id="chooseFiles" class="primary">Choose CSV files</button></div><input id="fileInput" type="file" accept=".csv,text/csv" multiple hidden><div class="upload-controls"><span class="thin">Report type</span><select id="importType"><option value="auto">Auto-detect from filename</option><option value="gross">Gross · order date</option><option value="net">Delivered · delivery date</option></select></div><div id="importPreview"></div>`)}${panel('How daily refresh works','One complete report per event date and stream',`<div class="quality-list"><div><b>01 · Upload</b><span>Choose both daily CSV files</span></div><div><b>02 · Validate</b><span>Review dates, row counts and values</span></div><div><b>03 · Import</b><span>All dashboard views refresh</span></div><div><b>04 · Preserve</b><span>Export a dashboard backup</span></div></div><p style="font-size:11px;margin-top:25px">Identical files are skipped using a content fingerprint, even if renamed. A changed report for an existing date replaces that stream’s full date partition after you review the preview. Rows within a report are preserved, including repeated product keys. Use complete daily exports; partial files would replace a full day with partial data.</p><p style="font-size:11px">Uploads are saved in this browser on this device. There is no scheduled server ingestion or cross-device sync. Download a portable dashboard or JSON backup to transfer your updated history.</p><div class="upload-controls"><button id="snapshotBtn">↓ Export full HTML · all history</button><button id="backupBtn">↓ Data backup</button><button id="restoreBtn">↥ Restore backup</button><input id="restoreInput" type="file" accept=".json" hidden></div>` )}</div><div class="grid-equal">${panel('Data quality monitor','Current date range and filters · Counts are item lines unless stated',`<div class="quality-list">${quality().map(([k,v])=>`<div><span>${k}</span><b>${num(v)}</b></div>`).join('')}</div><p class="thin" style="margin-top:20px">Repeated suborder/SKU keys can be valid distinct lines. They are retained. Blank attributes are displayed as Unmapped; category names are not merged automatically.</p>`)}${panel('Loaded source register','Most recent import activity · Reporting dates are event dates',`<div style="max-height:330px;overflow:auto">${[...data.imports].reverse().slice(0,30).map(x=>`<div style="padding:12px 0;border-bottom:1px solid var(--line)">${badge(x.stream==='gross'?'Gross':'Delivered',x.stream==='net'?'amber':'')} <b style="font-size:11px">${x.dates.map(esc).join(', ')}</b><p style="font-size:10px;word-break:break-all">${esc(x.file)}<br>${num(x.rows)} item lines · ${esc(x.at?new Date(x.at).toLocaleString('en-GB',{timeZone:'Asia/Dhaka'}):'Initial baseline')} Dhaka time</p></div>`).join('')}</div>`)}</div>`;}
const dictionary=[['GMV','Σ TotalSellingPrice from gross reports, grouped by Order Date. Includes cancelled orders present in the report.'],['GOS','Distinct SubOrderId in gross reports. These are suborders; they are not assumed to be unique customer checkout orders.'],['NMV','Σ TotalSellingPrice from delivered reports, grouped by DeliveredDate. Delivered merchandise value; no subsequent returns adjustment is available.'],['NOS','Distinct SubOrderId in delivered reports. Delivered events may originate from earlier order dates.'],['GIS / delivered items','Σ Quantity in the gross / delivered stream, respectively.'],['AOV / ASP','GMV ÷ GOS / GMV ÷ GIS. Net AOV uses NMV ÷ NOS.'],['Commission','Σ Commission from the source line items. It is displayed separately from merchandise value and purchase-cost contribution.'],['Delivered margin','(NMV − TotalCostPrice from delivered rows) ÷ NMV. Excludes operating costs and is not net profit.'],['Cancellation value rate','Cancelled-line GMV ÷ all gross GMV in the selected gross snapshot. Cancelled orders counts suborders with at least one cancelled line.'],['Snapshot cohort completion','Gross suborders whose every included line has Delivered or Complete status ÷ all gross suborders. It reflects the export snapshot only.'],['Delivery lead time','Time from Order Date to DeliveredDate per distinct delivered SubOrderId; earliest order timestamp and latest delivery timestamp. Invalid negative intervals excluded.'],['Period comparisons','Previous period uses the same number of calendar days immediately before the selected range. Previous month shifts both boundaries back one month, clamping to month-end. Growth is shown only when both streams’ relevant date coverage is complete.'],['Dimensions','Sales Person → KAM; Vendor → Shop account; Manufacturer → Brand; ItemCode → Seller SKU; Vendor Group Type → Account group type. Category 1–5 are the raw source levels.'],['Source order-level values','OrderTotal, vouchers, shipping and order discounts may repeat across item rows. They are not summed into headline merchandise metrics.'],['Order aggregation','Distinct IDs are recalculated for every filter, dimension and period. Adding suborder counts across categories, SKUs or brands can overcount a suborder with multiple items.'],['Coverage & storage','Missing report dates are unknown, not zero. This clean edition starts without sales or target records. Imports persist in this browser; portable exports include current history.']];
function guide(){return `<div class="insight-strip"><div class="insight-number">▷</div><div><strong>A six-stop leadership walkthrough</strong><p>Start with business scale, trace ownership, examine partners and products, then review fulfilment and economics.</p><div class="upload-controls"><button id="startWalk" class="primary">Start guided walkthrough</button><button id="printBtn">Print current view / Save PDF</button><button id="snapshotBtn">Export full HTML · all history</button></div></div></div><div class="guide-grid">${[['overview','01','Business pulse','Establish gross demand and delivered output, with coverage shown upfront.'],['kam','02','Commercial ownership','Rank KAMs, then use KAM × Seller to inspect each portfolio.'],['seller','03','Seller concentration','Identify high-value partners and click a seller for SKU, brand and category detail.'],['sku','04','Product demand','Review winning SKUs, brands, prices and item volumes.'],['operations','05','Execution quality','Inspect cancelled demand, snapshot order states and actual delivery lead times.'],['economics','06','Revenue quality','Separate merchandise value, purchase cost, commission and optional target attainment.']].map(([v,n,h,p])=>`<div class="guide-card" data-nav="${v}" tabindex="0" role="button"><div class="step">${n} / LEADERSHIP VIEW</div><h3>${h}</h3><p>${p}</p><span class="thin">Open view ↗</span></div>`).join('')}</div><div style="margin-top:22px">${panel('Metric dictionary & reporting policy','One consistent definition across all views',`<div class="definitions">${dictionary.map(([h,p])=>`<div><b>${h}</b><p>${p}</p></div>`).join('')}</div>`)}</div>`;}
async function baseRender(){const ticket=++renderTicket;from=$('#from').value;to=$('#to').value;compare=$('#compare').value;if(!from||!to||from>to){$('#content').innerHTML='<div class="empty"><b>Choose a valid date range</b>The start date must be on or before the end date.</div>';return;}if(E.dateRange(from,to).length>3660){$('#content').innerHTML='<div class="empty">Please select a range within 10 years.</div>';return;}let [a,b]=E.comparison(from,to,compare);setWorkStatus('Updating '+views.find(v=>v[0]===currentView)[2]+'…');await new Promise(resolve=>setTimeout(resolve,24));if(ticket!==renderTicket)return;try{let result=await preparedQuery(from,to,filters,currentView);if(ticket!==renderTicket)return;activeResult=result;filtered=result.rows;previous=result.prior;}catch(error){if(ticket===renderTicket){setWorkStatus('');$('#content').innerHTML='<div class="empty"><b>Could not update this view</b>'+esc(error.message)+'</div>';}return;}let v=views.find(x=>x[0]===currentView);$('#crumb').textContent=v[2];$('#title').textContent=v[3];$('#subtitle').textContent=v[4];$('#periodLabel').textContent=from===to?formatDate(from):formatDate(from)+' — '+formatDate(to);$$('#nav button').forEach(x=>x.classList.toggle('active',x.dataset.nav===currentView));let gc=coverageFor('gross',from,to),nc=coverageFor('net',from,to);$('#coverage').innerHTML=`<div class="coverage"><span><span class="live-dot" style="background:var(--green)"></span> Coverage: <b>Gross ${gc.have}/${gc.total} days</b> · <b>Delivered ${nc.have}/${nc.total} days</b> <span class="warning">${gc.have<gc.total||nc.have<nc.total?'· Partial period — missing dates are unknown':''}</span></span><span>${compare==='none'?'Comparison off':'Compared with '+formatDate(a)+' – '+formatDate(b)} · ${num(filtered.length)} item lines</span></div>`;
let body;switch(currentView){case'overview':body=overview();break;case'trends':body=trends();break;case'targets':body=targetsPage();break;case'mtd':body=biOverview(true);break;case'mom':body=biMom();break;case'hourly':body=biHourly();break;case'rankings':body=biRankings();break;case'kam':body=dimensionPage(['kam'],'KAM scorecard');break;case'kamseller':body=dimensionPage(['kam','seller'],'KAM × Shop account scorecard');break;case'seller':body=dimensionPage(['seller'],'Shop account scorecard');break;case'sku':body=dimensionPage(['sku'],'SKU scorecard');break;case'brand':body=dimensionPage(['brand'],'Brand scorecard');break;case'category':body=dimensionPage([categoryLevel],'Category scorecard');break;case'operations':body=operations();break;case'economics':body=economics();break;case'data':body=dataPage();break;default:body=guide();}$('#content').innerHTML=body;bindContent();setWorkStatus('');}
function nav(view){currentView=view;page=0;search='';sortKey='gmv';sortDir=-1;buildFilters();render();window.scrollTo({top:0,behavior:'smooth'});}
function calendarOptions(rows,year=''){if(rows.store){const dates=rows.store.dates;return {years:rows.store.years,months:[...new Set(dates.filter(d=>!year||d.startsWith(year+'-')).map(d=>d.slice(5,7)))].sort()};}let years=[...new Set(rows.map(r=>r.date.slice(0,4)))].sort().reverse(),months=[...new Set(rows.filter(r=>!year||r.date.startsWith(year+'-')).map(r=>r.date.slice(5,7)))].sort();return {years,months};}
function calendarRange(year,month,rows){const dates=rows.store?rows.store.dates:rows.map(r=>r.date).sort(),latest=dates.at(-1)||cleanToday();if(!dates.length)return [latest,latest];if(!year&&!month)return [dates[0],latest];if(!year)year=latest.slice(0,4);if(!month)return [year+'-01-01',year+'-12-31'];const last=new Date(Date.UTC(Number(year),Number(month),0)).getUTCDate();return [year+'-'+month+'-01',year+'-'+month+'-'+String(last).padStart(2,'0')];}
function filterMarkup(k,l){const opts=data.store.options(k);if(filters[k]&&!opts.includes(filters[k]))delete filters[k];const all=k==='categoryAny'?'All Categories':k==='group'?'All account group types':k==='kam'?'All KAMs':k==='seller'?'All shop accounts':k==='brand'?'All brands':'All '+l.toLowerCase();return `<label>${esc(l.toUpperCase())}<select data-options-key="${k}" data-filter="${k}" aria-label="Filter ${esc(l)}"><option value="">${all}</option>${filters[k]?`<option value="${esc(filters[k])}" selected>${esc(filters[k])}</option>`:''}</select></label>`;}
function buildFilters(){let top=currentView==='overview',html='';if(top){const {years,months}=calendarOptions(data.rows,topCalendar.year);if(topCalendar.year&&!years.includes(topCalendar.year))topCalendar={year:'',month:''};if(topCalendar.month&&!months.includes(topCalendar.month))topCalendar.month='';html=`<div class="topline-primary-filters"><label>YEAR<select id="topYear" aria-label="Filter Year"><option value="">All Years</option>${years.map(y=>`<option value="${y}" ${topCalendar.year===y?'selected':''}>${y}</option>`).join('')}</select></label><label>MONTH<select id="topMonth" aria-label="Filter Month"><option value="">All Months</option>${months.map(m=>`<option value="${m}" ${topCalendar.month===m?'selected':''}>${new Date('2026-'+m+'-01T12:00:00Z').toLocaleDateString('en-GB',{month:'long',timeZone:'UTC'})}</option>`).join('')}</select></label>${filterMarkup('group','Account group type')}${filterMarkup('categoryAny','All Categories')}</div><div class="topline-filter-note">Year and month set the reporting dates. All Categories searches Category 1–5 as supplied in your files.</div>`;const extra=dims.filter(([k])=>k!=='group'&&k!=='categoryAny'&&(k!=='cat1'||filters.cat1)),active=extra.filter(([k])=>filters[k]).length;html+=`<details class="additional-filters" ${active?'open':''}><summary>More filters${active?' · '+active+' active':''}</summary><div class="additional-filter-fields">${extra.map(([k,l])=>filterMarkup(k,l)).join('')}</div></details>`;}else{let visible=[...dims];if(filters.categoryAny&&!visible.some(([k])=>k==='categoryAny'))visible.push(['categoryAny','All Categories']);html=visible.map(([k,l])=>filterMarkup(k,l)).join('');}$('#filters').innerHTML=html;$$('[data-filter]').forEach(select=>select.onchange=()=>{filters[select.dataset.filter]=select.value;page=0;render();});if(top){$('#topYear').onchange=()=>changeTopCalendar('year',$('#topYear').value);$('#topMonth').onchange=()=>changeTopCalendar('month',$('#topMonth').value);}makeSearchableSelects($('#filters'));}
function changeTopCalendar(key,value){topCalendar[key]=value;if(key==='year'){if(!value)topCalendar.month='';else if(!calendarOptions(data.rows,value).months.includes(topCalendar.month))topCalendar.month='';}if(key==='month'&&value&&!topCalendar.year)topCalendar.year=calendarOptions(data.rows).years.find(y=>calendarOptions(data.rows,y).months.includes(value))||'';let[a,b]=calendarRange(topCalendar.year,topCalendar.month,data.rows);$('#from').value=a;$('#to').value=b;page=0;$$('[data-period]').forEach(x=>x.classList.remove('active'));buildFilters();render();}

function applyPeriod(p){topCalendar={year:'',month:''};let dates=data.store.dates,last=dates.at(-1);to=last;from=p==='all'?dates[0]:p==='month'?last.slice(0,8)+'01':p==='week'?E.shift(last,-6):last;$('#from').value=from;$('#to').value=to;buildFilters();$$('[data-period]').forEach(b=>b.classList.toggle('active',b.dataset.period===p));page=0;return render();}
async function drill(ds,labels){setWorkStatus('Opening detail…');let details={...filters},start=from,end=to;ds.forEach((d,i)=>{if(d==='date')start=end=labels[i];else if(d==='month'){start=labels[i]+'-01';end=labels[i]+'-31';}else details[d]=labels[i];});let result;try{result=await preparedQuery(start,end,details,'drill',[['seller'],['sku'],['brand'],['cat1']]);}catch(err){setWorkStatus('');return toast(err.message);}const rows=result.rows,a=result.summary;setWorkStatus('');let dim=ds.includes('sku')?'seller':ds.includes('kam')&&!ds.includes('seller')?'seller':'sku';let detail=E.group(rows,[dim]).sort((a,b)=>b.gmv-a.gmv).slice(0,20);showModal(labels.join(' / '),`<p class="thin">${formatDate(from)} – ${formatDate(to)} · Respects current global filters</p>${primaryKPIs(rows,true)}<div class="mini-stats">${mini('Gross items / Delivered items',num(a.gis)+' / '+num(a.nis))}${mini('Gross AOV','৳ '+money(a.aov))}${mini('Delivered margin',pct(a.margin))}</div>${ds.includes('sku')?`<div class="notice"><b>${esc(rows[0]?.name||'')}</b><br>Seller SKU(s): ${esc([...new Set(rows.map(r=>r.sellerSku))].join(', '))}<br>Observed gross ASP: ৳ ${money(a.asp)} · SKU: ${esc(labels[ds.indexOf('sku')])}</div>`:''}<h3 class="detail-heading">${dim==='seller'?'Shop accounts in this portfolio':'Top products in this selection'}</h3><div class="table-wrap"><table><thead><tr><th>${dim==='seller'?'Shop account':'SKU / product'}</th><th>GMV · ৳</th><th>GOS</th><th>NMV · ৳</th><th>NOS</th></tr></thead><tbody>${detail.map(x=>`<tr><td class="label">${esc(x.labels[0])}${dim==='sku'?'<small>'+esc(x.rows[0]?.name||'')+'</small>':''}</td><td>${money(x.gmv)}</td><td>${num(x.gos)}</td><td>${money(x.nmv)}</td><td>${num(x.nos)}</td></tr>`).join('')}</tbody></table></div><div class="grid-equal" style="margin-top:25px">${panel('Brand contribution','Gross value',bars(rows,'brand','gmv',5))}${panel('Category 1 contribution','Gross value',bars(rows,'cat1','gmv',5))}</div><div class="upload-controls"><button id="applyDrill" class="primary">Filter dashboard to this selection</button></div><p class="thin">Gross and delivered totals follow their own event dates. They are not the same order cohort.</p>`);$$('#modalBody [data-drill]').forEach(b=>b.onclick=()=>drill([...ds,b.dataset.drill],[...labels,b.dataset.val]));$('#applyDrill').onclick=()=>{ds.forEach((d,i)=>{if(d==='date'){$('#from').value=labels[i];$('#to').value=labels[i];}else if(d==='month'){$('#from').value=labels[i]+'-01';let dt=new Date(labels[i]+'-01T12:00:00Z');dt.setUTCMonth(dt.getUTCMonth()+1);dt.setUTCDate(0);$('#to').value=dt.toISOString().slice(0,10);}else filters[d]=labels[i];});ensureExtraFilters();buildFilters();$('#modal').close();page=0;render();};}
function ensureExtraFilters(){for(const k of Object.keys(filters))if(!dims.some(d=>d[0]===k)&&filters[k])dims.push([k,({categoryAny:'All Categories',sku:'SKU',cat2:'Category 2',cat3:'Category 3',cat4:'Category 4',cat5:'Category 5'})[k]||k]);}
function bindTable(){const container=$('#tableContainer');if(!container)$$('#content [data-sort]').forEach(b=>b.onclick=()=>{if(sortKey===b.dataset.sort)sortDir*=-1;else{sortKey=b.dataset.sort;sortDir=sortKey.startsWith('label')?1:-1;}render();});if(container){container.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{if(sortKey===b.dataset.sort)sortDir*=-1;else{sortKey=b.dataset.sort;sortDir=sortKey.startsWith('label')?1:-1;}container.innerHTML=tableHTML(prepareTable(tableDims),tableDims);bindTable();});let pp=$('#prevPage'),np=$('#nextPage');if(pp)pp.onclick=()=>{page--;container.innerHTML=tableHTML(prepareTable(tableDims),tableDims);bindTable();};if(np)np.onclick=()=>{page++;container.innerHTML=tableHTML(prepareTable(tableDims),tableDims);bindTable();};}$$('#content [data-tableindex]').forEach(r=>r.onclick=()=>drill(tableDims,tableRows[Number(r.dataset.tableindex)].labels));enhanceTables($('#content'));}
function legacyBindContent(){bindTable();if($('#chooseCleanupFolder'))$('#chooseCleanupFolder').onclick=scanCleanupFolder;if($('#showCleanupResults'))$('#showCleanupResults').onclick=showCleanupPlan;$$('#content [data-drill]').forEach(b=>{b.onclick=()=>drill([b.dataset.drill],[b.dataset.val]);b.onkeydown=e=>{if(e.key==='Enter')b.click()}});$$('#content [data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));$$('[data-trendmetric]').forEach(b=>b.onclick=()=>{trendMetric=b.dataset.trendmetric;render();});if($('#trendGrain'))$('#trendGrain').onchange=e=>{trendGrain=e.target.value;render();};if($('#categoryLevel'))$('#categoryLevel').onchange=e=>{categoryLevel=e.target.value;page=0;render();};if($('#tableSearch'))$('#tableSearch').oninput=e=>{search=e.target.value;page=0;clearTimeout(tableSearchTimer);tableSearchTimer=setTimeout(()=>{if($('#tableContainer')){$('#tableContainer').innerHTML=tableHTML(prepareTable(tableDims),tableDims);bindTable();}},120);};if($('#saveTarget'))$('#saveTarget').onclick=()=>{let n=Number($('#targetValue').value);if(!Number.isFinite(n)||n<0)return toast('Enter a non-negative target');target=n;try{localStorage.setItem('othoba-target',String(n))}catch{}render();toast('Planning target saved for this browser');};if($('#dropZone')){let dz=$('#dropZone');dz.onclick=()=>$('#fileInput').click();dz.onkeydown=e=>{if(e.key==='Enter')$('#fileInput').click();};dz.ondragover=e=>{e.preventDefault();dz.classList.add('drag')};dz.ondragleave=()=>dz.classList.remove('drag');dz.ondrop=e=>{e.preventDefault();dz.classList.remove('drag');stageFiles([...e.dataTransfer.files])};$('#fileInput').onchange=e=>stageFiles([...e.target.files]);}if($('#snapshotBtn'))$('#snapshotBtn').onclick=snapshot;if($('#backupBtn'))$('#backupBtn').onclick=async()=>{try{setWorkStatus('Preparing compressed-record backup…');download('Othoba_Performance_Backup_'+data.store.dates.at(-1)+'.json',await backgroundTask('backup'),'application/json');}catch(err){toast(err.message);}finally{setWorkStatus('');}};if($('#restoreBtn'))$('#restoreBtn').onclick=()=>$('#restoreInput').click();if($('#restoreInput'))$('#restoreInput').onchange=async e=>{try{let file=e.target.files[0];if(!file)return;let next=Packed.state(await backgroundTask('restore',{text:await file.text()}));showModal('Restore dashboard history',`<p>This backup contains <b>${num(next.rows.length)} item lines</b> across ${next.store.dates.length} dates. Restoring replaces the current browser history.</p><div class="upload-controls"><button id="confirmRestore" class="primary">Restore this backup</button><button id="cancelRestore">Cancel</button></div>`);$('#cancelRestore').onclick=()=>$('#modal').close();$('#confirmRestore').onclick=async()=>{try{await commitData(next);$('#modal').close();filters={};buildFilters();applyPeriod('latest');toast('Backup restored');}catch(err){toast(err.message)}};}catch(err){toast('Restore failed: '+err.message)}};if($('#startWalk'))$('#startWalk').onclick=()=>startWalk();if($('#printBtn'))$('#printBtn').onclick=()=>window.print();makeSearchableSelects(document);}

function validateBackup(obj){if(!obj||obj.version!==1||!Array.isArray(obj.rows)||!obj.rows.length||!Array.isArray(obj.imports))throw Error('Invalid backup format');for(const r of obj.rows){if(!['gross','net'].includes(r.stream)||!r.id||!/^\d{4}-\d{2}-\d{2}$/.test(r.date))throw Error('Invalid row identifiers');for(const k of Object.keys(E.nums))if(typeof r[k]!=='number'||!Number.isFinite(r[k]))throw Error('Invalid numeric field '+k);for(const k of Object.keys(E.fields))if(typeof r[k]!=='string')throw Error('Missing text field '+k);for(const k of ['ordered','delivered','shipped'])if(typeof r[k]!=='string'||(r[k]&&E.dateISO(r[k])!==r[k]))throw Error('Invalid timestamp '+k);if(r.date!==(r.stream==='net'?r.delivered:r.ordered).slice(0,10))throw Error('Event date mismatch');for(let i=1;i<=5;i++)if(typeof r['cat'+i]!=='string')throw Error('Missing category');}for(const i of obj.imports)if(!Array.isArray(i.dates)||typeof i.file!=='string'||!['gross','net'].includes(i.stream)||typeof i.rows!=='number')throw Error('Invalid source register');return obj;}
function download(name,content,type){let u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000)}
function safeCSV(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s)&&typeof v!=='number')s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
