let cleanupPlan=null;
function folderCleanupPanel(){return panel('Local folder · exact duplicate cleaner','Select Downloads → Otthoba Daily Sales Dump in Chrome or Edge',`<p>Scan the selected folder’s CSV files by their exact contents. The original report is kept; extra copies can be moved into <b>_Duplicates_Review</b> inside that folder. Files stay on your computer.</p><div class="upload-controls"><button id="chooseCleanupFolder" class="primary">Choose folder & scan duplicates</button><button id="showCleanupResults" ${cleanupPlan?'':'disabled'}>View last scan</button></div><p class="thin">Only CSV files directly inside the chosen folder are checked. Subfolders are excluded. Scanning does not change files. Cleanup runs only when you select “Move duplicate copies”.</p><div id="folderCleanupStatus"></div>`);}
async function binaryFingerprint(file){let bytes=new Uint8Array(await file.arrayBuffer());if(globalThis.crypto?.subtle){let hash=new Uint8Array(await crypto.subtle.digest('SHA-256',bytes));return {hash:[...hash].map(x=>x.toString(16).padStart(2,'0')).join(''),algorithm:'SHA-256'};}let chunks=[];for(let i=0;i<bytes.length;i+=16384)chunks.push(String.fromCharCode(...bytes.subarray(i,i+16384)));return {hash:await E.fingerprint(btoa(chunks.join('')),'binary-csv'),algorithm:'SHA-256 of encoded bytes'};}
function preferOriginal(a,b){const copy=n=>/\s*\(\d+\)(?=\.[^.]+$)|\bcopy\b/i.test(n)?1:0;return copy(a.name)-copy(b.name)||a.modified-b.modified||a.name.localeCompare(b.name);}
function groupExactCopies(entries){const byHash=new Map();for(const e of entries){const key=e.size+'|'+e.algorithm+'|'+e.hash;if(!byHash.has(key))byHash.set(key,[]);byHash.get(key).push(e);}return [...byHash.values()].filter(a=>a.length>1).map(a=>{a.sort(preferOriginal);return {keep:a[0],duplicates:a.slice(1)};});}
async function scanCleanupFolder(){if(!window.showDirectoryPicker){showModal('Folder access is unavailable','<p>Open this downloaded HTML directly in a current desktop version of Chrome or Edge, then choose the folder. Folder write access may be unavailable in a preview, iframe, Safari or Firefox.</p>');return;}let dir;try{dir=await window.showDirectoryPicker({id:'othoba-daily-sales-dump',mode:'read',startIn:'downloads'});}catch(err){if(err.name!=='AbortError')toast('Could not open folder: '+err.message);return;}
 const status=$('#folderCleanupStatus');if(status)status.innerHTML='<p>Scanning '+esc(dir.name)+'…</p>';let sizes=new Map(),csvCount=0,skipped=0,hashes=[],warnings=[];for await(const [name,handle]of dir.entries()){if(handle.kind!=='file'||!/\.csv$/i.test(name)){skipped++;continue;}try{let file=await handle.getFile();csvCount++;let e={name,handle,size:file.size,modified:file.lastModified};if(!sizes.has(file.size))sizes.set(file.size,[]);sizes.get(file.size).push(e);}catch(err){warnings.push(name+': '+err.message);}}
 let candidates=[...sizes.values()].filter(a=>a.length>1).flat(),done=0;for(const entry of candidates){try{let file=await entry.handle.getFile();if(file.size!==entry.size||file.lastModified!==entry.modified)throw Error('File changed during scan; skipped');Object.assign(entry,await binaryFingerprint(file));hashes.push(entry);}catch(err){warnings.push(entry.name+': '+err.message);}done++;if(status&&status.isConnected)status.innerHTML='<p>Checking file contents '+done+' / '+candidates.length+'…</p>';}
 cleanupPlan={directory:dir,name:dir.name,at:new Date().toISOString(),csvCount,skipped,warnings,groups:groupExactCopies(hashes)};if(status&&status.isConnected)status.innerHTML='<p class="success">Scan complete. '+cleanupPlan.groups.reduce((n,g)=>n+g.duplicates.length,0)+' exact duplicate copies found. No files changed.</p>';showCleanupPlan();}
function showCleanupPlan(){if(!cleanupPlan)return;const plan=cleanupPlan,duplicates=plan.groups.reduce((n,g)=>n+g.duplicates.length,0),bytes=plan.groups.reduce((n,g)=>n+g.duplicates.reduce((s,d)=>s+d.size,0),0);showModal('Duplicate scan · '+plan.name,`<p>${num(plan.csvCount)} CSV files scanned · <b>${num(duplicates)} duplicate copies</b> · ${(bytes/1048576).toFixed(2)} MB in extra copies. ${esc(plan.skipped)} non-CSV entries/subfolders excluded.</p><p>One file is kept per exact-content group. Files without a copy suffix are preferred, followed by the oldest modification date. Nothing has been moved yet.</p>${duplicates?`<div class="table-wrap"><table><thead><tr><th>Keep this original</th><th>Move this duplicate copy</th><th>Size · bytes</th></tr></thead><tbody>${plan.groups.flatMap(g=>g.duplicates.map(d=>`<tr><td class="label">${esc(g.keep.name)}</td><td class="label">${esc(d.name)}</td><td>${num(d.size)}</td></tr>`)).join('')}</tbody></table></div><div class="notice" style="margin-top:20px">The next action copies each duplicate into <b>_Duplicates_Review</b>, verifies the saved copy, and removes the extra copy from the main folder. The kept original remains in place. You can recover moved files from the review folder.</div><button id="moveDuplicateCopies" class="primary">Move ${num(duplicates)} duplicate copies to review folder</button>`:'<div class="success" style="padding:20px 0">No exact duplicate CSV files found. Your folder is unchanged.</div>'}${plan.warnings.length?'<p class="error">Skipped files: '+plan.warnings.map(esc).join('<br>')+'</p>':''}`);if($('#moveDuplicateCopies'))$('#moveDuplicateCopies').onclick=moveDuplicateCopies;}
async function uniqueRecoveryFile(dir,name){let n=name;for(let i=0;i<1000;i++){try{await dir.getFileHandle(n);n=i+'__'+name;}catch(err){if(err.name==='NotFoundError')return dir.getFileHandle(n,{create:true});throw err;}}throw Error('Could not allocate a unique recovery filename');}
async function recoverableCleanup(plan,onProgress=()=>{}){const recovery=await plan.directory.getDirectoryHandle('_Duplicates_Review',{create:true}),run=new Date().toISOString().replace(/[:.]/g,'-'),moved=[],errors=[];for(const group of plan.groups){for(const duplicate of group.duplicates){try{if(await group.keep.handle.isSameEntry(duplicate.handle))throw Error('Original and duplicate refer to the same file');let keep=await group.keep.handle.getFile(),source=await duplicate.handle.getFile();let[k,s]=await Promise.all([binaryFingerprint(keep),binaryFingerprint(source)]);if(k.hash!==group.keep.hash||s.hash!==duplicate.hash||k.hash!==s.hash||source.size!==keep.size)throw Error('File contents changed since scan; rescan required');const backup=await uniqueRecoveryFile(recovery,run+'__'+duplicate.name),writer=await backup.createWritable();await writer.write(source);await writer.close();let saved=await backup.getFile(),check=await binaryFingerprint(saved);if(saved.size!==source.size||check.hash!==s.hash)throw Error('Recovery copy did not verify; original duplicate retained');let sourceNow=await duplicate.handle.getFile(),keepNow=await group.keep.handle.getFile();if((await binaryFingerprint(sourceNow)).hash!==s.hash||(await binaryFingerprint(keepNow)).hash!==k.hash)throw Error('File changed during backup; original duplicate retained');await plan.directory.removeEntry(duplicate.name);moved.push({original:duplicate.name,kept:group.keep.name,recovery:backup.name,bytes:source.size,hash:s.hash,algorithm:s.algorithm});}catch(err){errors.push({file:duplicate.name,reason:err.message});}onProgress(moved.length,errors.length);}}
 if(moved.length){try{let manifest=await uniqueRecoveryFile(recovery,'cleanup-log-'+run+'.json'),w=await manifest.createWritable();await w.write(JSON.stringify({folder:plan.name,at:new Date().toISOString(),moved,errors},null,2));await w.close();}catch(err){errors.push({file:'Cleanup log',reason:err.message});}}return {moved,errors};}
async function moveDuplicateCopies(){const plan=cleanupPlan,button=$('#moveDuplicateCopies');try{let granted=await plan.directory.queryPermission({mode:'readwrite'});if(granted!=='granted')granted=await plan.directory.requestPermission({mode:'readwrite'});if(granted!=='granted')return toast('Folder write permission was not granted. No files changed.');button.disabled=true;const result=await recoverableCleanup(plan,(ok,fail)=>button.textContent='Moved '+ok+' copies'+(fail?' · '+fail+' skipped':''));cleanupPlan=null;showModal('Folder cleanup complete',`<p><b>${num(result.moved.length)} duplicate copies moved</b> into <b>_Duplicates_Review</b>. One original file per duplicate group remains in the main folder.</p><p>Files are recoverable from the review folder. ${result.moved.length?'A cleanup log was also saved there.':''}</p>${result.errors.length?'<p class="error">Not moved:<br>'+result.errors.map(x=>esc(x.file)+': '+esc(x.reason)).join('<br>')+'</p>':''}`);toast(result.moved.length+' duplicate copies moved to review folder');}catch(err){if(button?.isConnected)button.disabled=false;toast('Cleanup stopped: '+err.message);}}
