function setWorkStatus(message){let el=$('#workStatus');if(el){el.textContent=message;el.hidden=!message;}}
async function ensureBackground(){if(backgroundReady)return backgroundReady;backgroundReady=(async()=>{let source=window.__WORKER_SOURCE__;if(!source){source=(await Promise.all(['packed.js','engine.js','worker.js'].map(x=>fetch(assetUrl(x)).then(r=>r.text())))).join('\n');window.__WORKER_SOURCE__=source;}if(typeof Worker!=='undefined'){try{let url=URL.createObjectURL(new Blob([source],{type:'text/javascript'}));backgroundWorker=new Worker(url);URL.revokeObjectURL(url);backgroundWorker.onmessage=e=>{let pending=backgroundCalls.get(e.data.id);if(!pending)return;backgroundCalls.delete(e.data.id);e.data.error?pending.reject(Error(e.data.error)):pending.resolve(e.data.result);};backgroundWorker.onerror=e=>{for(const call of backgroundCalls.values())call.reject(Error(e.message||'Background processor failed'));backgroundCalls.clear();};}catch{backgroundWorker=null;}}})();return backgroundReady;}
async function backgroundTask(type,payload={}){await ensureBackground();if(!backgroundWorker)return runWorkerTask(type,payload);return new Promise((resolve,reject)=>{const id=++backgroundSeq;backgroundCalls.set(id,{resolve,reject});backgroundWorker.postMessage({id,type,payload},payload?.payload?.bytes?[payload.payload.bytes]:[]);});}
