function drawBulkPreview(){let box=$('#importPreview');if(!box||!bulkState)return;let p=bulkState;box.innerHTML=`<div class="bulk-summary"><h3>Historical batch preview</h3><div class="bulk-metrics"><div><b>${num(p.scanned)}</b><span>Files checked</span></div><div><b>${num(p.ready)}</b><span>Ready stream dates</span></div><div><b>${num(p.exactDuplicates)}</b><span>Exact duplicate files</span></div><div><b>${num(p.normalizedDuplicateDates)}</b><span>Matching date copies</span></div><div class="${p.unresolved?'negative':''}"><b>${num(p.unresolved)}</b><span>Overlaps to review</span></div><div><b>${num(p.invalid)}</b><span>Invalid files</span></div></div><p>Selected import: <b>${num(p.rows)} item lines</b> · Gross ৳ ${bulkMoney(p.gmv)} · Delivered ৳ ${bulkMoney(p.nmv)}. ${num(p.replacements)} saved stream date(s) will be replaced. ${num(p.unchanged)} date(s) already match saved history; ${num(p.excluded)} explicitly excluded.</p>${!p.ready&&!p.unresolved&&!p.invalid&&p.unchanged>0?'<p class="notice"><b>These files match saved history.</b> To reimport, click Override beside any file below. Skip preserves the currently saved records. Previewing alone never saves files.</p>':''}<p class="thin">Matching normalized daily rows are skipped even when row order differs. Different versions are never combined silently. Repeated rows inside a selected report are retained. Use complete daily exports.</p>${bulkCancelled?'<p class="notice">Scan cancelled after the checked files. Nothing has been saved.</p>':''}${p.invalid?'<p class="error">'+num(p.invalid)+' file(s) could not be read. Valid files remain in this preview. See the file results below.</p>':''}${p.unresolved?'<p class="notice"><b>Different reports cover the same date.</b> Choose a version below, use the latest CreatedOn timestamps, or explicitly exclude the unresolved dates. The rest of the batch stays ready.</p>':''}<div class="upload-controls bulk-actions"><button id="latestBulkExports" ${p.unresolved?'':'disabled'}>Use latest dated exports</button><button id="skipBulkOverlaps" ${p.unresolved?'':'disabled'}>Exclude unresolved dates</button><button id="bulkLog">Export file results CSV</button><button id="discardBulk">Discard preview</button></div><p class="thin">Latest dated exports uses only a valid CreatedOn timestamp in the filename. Missing or tied timestamps remain for review. A newer filename does not prove a report is complete; check the selected row counts.</p>${p.overlapping?'<div class="bulk-review-heading"><h3>Overlapping reporting dates</h3><input id="bulkSearch" type="search" placeholder="Search date or filename…" aria-label="Search overlap dates" value="'+esc(bulkFind)+'"></div><div id="bulkOverlapRows"></div>':''}<details class="bulk-file-results" open><summary>File-by-file decisions · ${num(p.scanned)} files</summary><div id="bulkFileRows"></div></details><div class="bulk-save"><button id="commitBulk" class="primary" ${bulkCommitReady()?'':'disabled'}>Import selected reports</button><span>${p.unresolved?num(p.unresolved)+' overlap(s) need a selection or exclusion.':p.ready?'Review the selected totals, then save all selected dates together.':'No new dates selected. Use Override beside a file to reimport it, or leave it skipped.'}</span></div></div>`;if(p.overlapping)drawBulkOverlaps();drawBulkFileRows();$('#latestBulkExports').onclick=()=>bulkPolicy('latest');$('#skipBulkOverlaps').onclick=()=>bulkPolicy('skip');$('#bulkLog').onclick=exportBulkLog;$('#discardBulk').onclick=async()=>{await backgroundTask('bulkDiscard');bulkState=null;box.innerHTML='<p>Preview discarded. Saved reporting history was not changed.</p>';};$('#commitBulk').onclick=saveBulkImport;if($('#bulkSearch'))$('#bulkSearch').oninput=e=>{bulkFind=e.target.value;bulkPage=0;drawBulkOverlaps();};}
function drawBulkOverlaps(){let list=bulkRows(),limit=20,totalPages=Math.max(1,Math.ceil(list.length/limit));bulkPage=Math.min(bulkPage,totalPages-1);let rows=list.slice(bulkPage*limit,(bulkPage+1)*limit),root=$('#bulkOverlapRows');if(!root)return;root.innerHTML=`<div class="bulk-overlap-list">${rows.map((b,i)=>`<div class="bulk-date ${b.choice?'resolved':'unresolved'}"><div class="bulk-date-title"><b>${b.date} · ${b.stream==='gross'?'Gross':'Delivered'}</b><span>${b.choice==='skip'?'Excluded':b.choice?'Selected':'Choice required'}</span></div><div class="bulk-options">${b.options.map(o=>`<div class="bulk-version"><b>${o.saved?'Saved history':o.files.length?esc(o.files[0]):'Selected report'}</b>${o.files.length>1?'<small>+'+(o.files.length-1)+' identical normalized copies</small>':''}<span>${num(o.rows)} lines · ৳ ${bulkMoney(o.value)}</span></div>`).join('')}</div><label class="bulk-pick">Keep for this date<select data-bulkkey="${esc(b.key)}" aria-label="Choose report for ${b.date} ${b.stream}"><option value="" ${!b.choice?'selected':''}>Choose a report version…</option>${b.options.map(o=>`<option value="${o.id}" ${b.choice===o.id?'selected':''}>${o.saved?'Keep saved history':esc(o.files[0])} · ${o.rows} lines · ৳ ${bulkMoney(o.value)}</option>`).join('')}<option value="skip" ${b.choice==='skip'?'selected':''}>Skip this date and preserve any saved history</option></select></label><small>${esc(b.reason)}</small></div>`).join('')||'<p>No overlaps match the search.</p>'}</div><div class="bulk-paging"><span>${list.length?bulkPage*limit+1:0}–${Math.min((bulkPage+1)*limit,list.length)} of ${list.length} overlapping stream dates</span><button id="bulkPrev" ${bulkPage===0?'disabled':''}>Previous overlaps</button><button id="bulkNext" ${bulkPage+1>=totalPages?'disabled':''}>Next overlaps</button></div>`;$$('[data-bulkkey]').forEach(select=>select.onchange=async()=>{try{setWorkStatus('Updating the batch selection…');bulkState=await backgroundTask('bulkChoose',{key:select.dataset.bulkkey,choice:select.value||null});drawBulkPreview();}catch(error){toast(error.message);}finally{setWorkStatus('');}});$('#bulkPrev').onclick=()=>{bulkPage--;drawBulkOverlaps();};$('#bulkNext').onclick=()=>{bulkPage++;drawBulkOverlaps();};makeSearchableSelects(root);}
function bulkVisibleFiles(){let q=bulkFileFind.toLowerCase();return (bulkState?.files||[]).filter(f=>!q||(f.file+' '+f.status+' '+f.stream+' '+(f.dates||[]).join(' ')).toLowerCase().includes(q)).sort((a,b)=>{let x=a[bulkFileSort],y=b[bulkFileSort];return (typeof x==='number'?x-y:String(x).localeCompare(String(y)))*bulkFileDir;});}
function drawBulkFileRows(){let root=$('#bulkFileRows');if(!root)return;let list=bulkVisibleFiles(),limit=25,pages=Math.max(1,Math.ceil(list.length/limit));bulkFilePage=Math.min(bulkFilePage,pages-1);let shown=list.slice(bulkFilePage*limit,(bulkFilePage+1)*limit);root.innerHTML=`<p class="thin">Override selects this file's complete date records for replacement, including an identical file already saved. Skip excludes this file from the batch and preserves saved history. Nothing changes until Import selected reports. If files overlap, the most recent Override choice takes that date; the other file is marked partly selected.</p><div class="bulk-file-tools"><input id="bulkFileSearch" type="search" aria-label="Search import files" placeholder="Search filename, status or date…" value="${esc(bulkFileFind)}"><div><select id="bulkFileSort" aria-label="Sort import files"><option value="file" ${bulkFileSort==='file'?'selected':''}>Filename</option><option value="status" ${bulkFileSort==='status'?'selected':''}>Status</option><option value="rows" ${bulkFileSort==='rows'?'selected':''}>Item lines</option></select><button id="bulkFileAscending">↑ Low to high</button><button id="bulkFileDescending">↓ High to low</button><button id="copyBulkFiles">Copy file results</button></div></div><div class="bulk-decision-list">${shown.map(f=>`<article class="bulk-file-decision ${f.excluded?'file-excluded':f.manualOverride?'file-overridden':''}"><div class="bulk-file-info"><b>${esc(f.file)}</b><span class="${f.sourceStatus==='invalid'?'negative':''}">${esc(f.status)} · ${f.stream==='net'?'Delivered':f.stream==='gross'?'Gross':'Unknown stream'} · ${num(f.rows)} item lines</span><small>${(f.dates||[]).length?esc(f.dates.join(', ')):'No valid dates'}${f.savedDates?.length?' · Verified saved: '+f.savedDates.length+' date(s)':''}</small>${f.pendingDates.length?'<small class="negative">Needs review: '+f.pendingDates.map(esc).join(', ')+'</small>':''}${f.skippedDates.length?'<small>Not selected: '+f.skippedDates.map(esc).join(', ')+'</small>':''}${f.note?'<small>'+esc(f.note)+'</small>':''}</div><div class="bulk-file-buttons"><button class="primary" data-file-override="${f.id}" aria-label="Override ${esc(f.file)}" ${!f.canOverride||bulkDecisionBusy?'disabled':''}>Override</button><button data-file-skip="${f.id}" aria-label="Skip ${esc(f.file)}" ${!f.canOverride||f.excluded||bulkDecisionBusy?'disabled':''}>Skip</button></div></article>`).join('')||'<p>No files match the search.</p>'}</div><div class="bulk-paging"><span>${list.length?bulkFilePage*limit+1:0}–${Math.min((bulkFilePage+1)*limit,list.length)} of ${num(list.length)} files · All files available across pages</span><button id="bulkFilesPrev" ${bulkFilePage===0?'disabled':''}>Previous files</button><button id="bulkFilesNext" ${bulkFilePage+1>=pages?'disabled':''}>Next files</button></div>`;$('#bulkFileSearch').oninput=e=>{bulkFileFind=e.target.value;bulkFilePage=0;let caret=e.target.selectionStart;drawBulkFileRows();$('#bulkFileSearch').focus();$('#bulkFileSearch').setSelectionRange(caret,caret);};for(let[id,dir]of [['bulkFileAscending',1],['bulkFileDescending',-1]])$('#'+id).onclick=()=>{bulkFileSort=$('#bulkFileSort').value;bulkFileDir=dir;bulkFilePage=0;drawBulkFileRows();};$('#bulkFilesPrev').onclick=()=>{bulkFilePage--;drawBulkFileRows();};$('#bulkFilesNext').onclick=()=>{bulkFilePage++;drawBulkFileRows();};$$('[data-file-override]').forEach(b=>b.onclick=()=>bulkFileDecision(b.dataset.fileOverride,'override'));$$('[data-file-skip]').forEach(b=>b.onclick=()=>bulkFileDecision(b.dataset.fileSkip,'skip'));$('#copyBulkFiles').onclick=async()=>{let rows=[['Filename','Status','Stream','Item lines','Dates'],...list.map(f=>[f.file,f.status,f.stream,f.rows,(f.dates||[]).join('; ')])],text=rows.map(r=>r.join('\t')).join('\n');try{await navigator.clipboard.writeText(text);toast(num(list.length)+' file results copied');}catch{showModal('Copy file results','<textarea id="bulkManualCopy" style="width:100%;height:320px">'+esc(text)+'</textarea>');$('#bulkManualCopy').select();}};makeSearchableSelects(root);}
async function bulkFileDecision(fileId,action){if(bulkBusy||bulkDecisionBusy)return;bulkDecisionBusy=true;if($('#commitBulk'))$('#commitBulk').disabled=true;$$('[data-file-override],[data-file-skip]').forEach(b=>b.disabled=true);try{setWorkStatus(action==='override'?'Selecting file for replacement…':'Skipping file…');bulkState=await backgroundTask('bulkFileAction',{fileId,action});lastBulkReport=bulkState.files;}catch(error){toast(error.message);}finally{bulkDecisionBusy=false;setWorkStatus('');drawBulkPreview();}}

async function bulkPolicy(mode){try{setWorkStatus('Resolving selected overlaps…');bulkState=await backgroundTask('bulkPolicy',{mode});drawBulkPreview();toast(bulkState.policyResolved+' overlapping date(s) '+(mode==='latest'?'selected using CreatedOn timestamps':'excluded')+'.');}catch(error){toast(error.message);}finally{setWorkStatus('');}}
function exportBulkLog(){let files=bulkState?.files||lastBulkReport;if(!files.length)return toast('No batch results to export');let rows=[['Filename','Status','Stream','Source item lines','Selected or saved dates','Not selected dates','Pending dates','Details'],...files.map(f=>[f.file,f.status,f.stream,f.rows,f.selectedDates.join('; '),f.skippedDates.join('; '),f.pendingDates.join('; '),f.note])];download('Othoba_Bulk_Import_Results.csv','\uFEFF'+rows.map(r=>r.map(safeCSV).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
async function stageFiles(files){if(!files.length)return;if(bulkBusy)return toast('A batch is running. Cancel its scan before selecting another batch.');bulkBusy=true;bulkCancelled=false;bulkState=null;lastBulkReceipt=null;bulkFind='';bulkPage=0;bulkFileFind='';bulkFilePage=0;let box=$('#importPreview'),override=$('#importType').value,done=0,duplicates=0,invalid=0;function scanning(file=''){bulkProgressState={file,done,total:files.length,duplicates,invalid};box=$('#importPreview');if(!box?.isConnected)return;box.innerHTML=`<div class="bulk-progress"><b>Checking historical reports · ${done} / ${files.length}</b><progress max="${files.length}" value="${done}"></progress><span>${esc(file)}</span><small>${duplicates} duplicate file(s) skipped · ${invalid} invalid file(s) · Saved history has not changed</small><button id="cancelBulkScan">Cancel scan</button></div>`;$('#cancelBulkScan').onclick=()=>{bulkCancelled=true;$('#cancelBulkScan').disabled=true;$('#cancelBulkScan').textContent='Cancelling after the current file…';};}try{await backgroundTask('bulkStart');for(let file of files){if(bulkCancelled)break;scanning(file.name);setWorkStatus('Checking report '+(done+1)+' / '+files.length+' · '+file.name);let result=await backgroundTask('bulkFile',{file,override});done++;if(result.status==='duplicate')duplicates++;if(result.status==='invalid')invalid++;}bulkState=await backgroundTask('bulkPreview');lastBulkReport=bulkState.files;bulkProgressState=null;drawBulkPreview();if(!bulkState.ready&&!bulkState.unresolved&&!bulkState.invalid)toast('Reports checked. Saved rows verified. Use the file-by-file Override buttons to reimport any report.');}catch(error){if(box?.isConnected)box.innerHTML='<div class="error">Could not finish the scan: '+esc(error.message)+'. Saved history has not changed. Select the files again to retry.</div>';}finally{bulkBusy=false;setWorkStatus('');if($('#fileInput'))$('#fileInput').value='';}}
async function saveBulkImport(){if(bulkBusy||!bulkCommitReady())return;bulkBusy=true;let btn=$('#commitBulk');btn.disabled=true;try{if(!db)throw Error('Browser storage is unavailable. Open the tool in Chrome or Edge with local storage enabled.');setWorkStatus('Combining selected dates and saving history…');lastBulkReport=await backgroundTask('bulkReport');let importedDates=bulkState.ready,ignored=bulkState.invalid+bulkState.excluded;let next=await backgroundTask('bulkCommit');await saveDB(next);await backgroundTask('bulkAccept');data=Packed.state(next);queryResults.clear();preparedTables=new WeakMap();persisted=true;bulkState=null;updateSaved();buildFilters();await applyPeriod('latest');lastBulkReceipt={dates:importedDates,ignored};let box=$('#importPreview');if(box){box.innerHTML=`<div class="success"><b>${num(importedDates)} stream date(s) saved.</b><p>Reporting history and all dashboard views are updated. ${ignored?num(ignored)+' invalid file(s) or excluded dates were not imported.':''}</p><button id="savedBulkLog">Export file results CSV</button><button id="savedBulkHtml">Export full HTML with all history</button></div>`;$('#savedBulkLog').onclick=exportBulkLog;$('#savedBulkHtml').onclick=snapshot;}toast('Selected reports saved. Export the full HTML to share all history.');}catch(error){if(btn?.isConnected)btn.disabled=false;toast('Import not saved: '+error.message);}finally{bulkBusy=false;setWorkStatus('');}}
function salesBindContent(){consoleBindContent();if(currentView!=='data')return;if(bulkState&&!bulkBusy)drawBulkPreview();else if(bulkBusy&&bulkProgressState){let p=bulkProgressState,box=$('#importPreview');box.innerHTML='<div class="bulk-progress"><b>Historical scan in progress · '+p.done+' / '+p.total+'</b><progress max="'+p.total+'" value="'+p.done+'"></progress><span>'+esc(p.file)+'</span><button id="cancelBulkScan">Cancel scan</button></div>';$('#cancelBulkScan').onclick=()=>{bulkCancelled=true;$('#cancelBulkScan').disabled=true;};}else if(lastBulkReceipt){$('#importPreview').innerHTML='<div class="success"><b>'+num(lastBulkReceipt.dates)+' stream date(s) saved.</b><p>Reporting history is updated.</p><button id="savedBulkLog">Export file results CSV</button><button id="savedBulkHtml">Export full HTML with all history</button></div>';$('#savedBulkLog').onclick=exportBulkLog;$('#savedBulkHtml').onclick=snapshot;}}

// Target registry shared by the browser and background worker.
var TargetEngine=(()=>{
const scopes={kam:{label:'KAM',column:'KAM',field:'kam'},seller:{label:'Seller',column:'Seller',field:'seller'},category:{label:'Category',column:'Category',field:'cat1'},vertical:{label:'Vertical',column:'Vertical',field:'business'}};
const metrics=['gmv','gos','nmv','nos'];
const col={gmv:'GMVTarget',gos:'GOSTarget',nmv:'NMVTarget',nos:'NOSTarget'};
const key=r=>JSON.stringify([r.scope,r.cadence,r.period,r.level||'',r.entity]);
const equal=(a,b)=>metrics.every(k=>a[k]===b[k]);
function parse(text,scope,cadence,file){if(!scopes[scope]||!['daily','monthly'].includes(cadence))throw Error('Select a target level and frequency.');let rows=Engine.parseCSV(text),dateCol=cadence==='daily'?'Date':'Month',entityCol=scopes[scope].column,required=[dateCol,entityCol,...(scope==='category'?['CategoryLevel']:[])];for(let c of required)if(!(c in rows[0]))throw Error('Missing column '+c+'. Download the matching template.');if(!metrics.some(k=>col[k] in rows[0]))throw Error('At least one target metric column is required.');return rows.map((r,i)=>{let period=(r[dateCol]||'').trim(),entity=(r[entityCol]||'').trim(),level=scope==='category'?(r.CategoryLevel||'').trim():'';if(!entity)throw Error('Row '+(i+2)+': '+entityCol+' is required.');if(cadence==='daily'){if(!/^\d{4}-\d{2}-\d{2}$/.test(period)||Engine.dateISO(period).slice(0,10)!==period)throw Error('Row '+(i+2)+': Date must be YYYY-MM-DD.');}else if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(period))throw Error('Row '+(i+2)+': Month must be YYYY-MM.');if(scope==='category'&&!/^[1-5]$/.test(level))throw Error('Row '+(i+2)+': CategoryLevel must be 1 to 5.');let x={scope,cadence,period,entity,level,file};for(let k of metrics){let v=(r[col[k]]||'').trim();x[k]=v===''?null:Number(v.replace(/,/g,''));if(x[k]!==null&&(!Number.isFinite(x[k])||x[k]<0||(['gos','nos'].includes(k)&&!Number.isInteger(x[k]))))throw Error('Row '+(i+2)+': '+col[k]+' must be non-negative'+(['gos','nos'].includes(k)?' and a whole number.':'.'));}if(metrics.every(k=>x[k]===null))throw Error('Row '+(i+2)+': enter at least one target.');return x;});}
function merge(existing,incoming){let map=new Map(existing.map(r=>[key(r),r])),seen=new Map(),added=0,replaced=0,duplicates=0;for(let r of incoming){let k=key(r);if(seen.has(k)){if(!equal(seen.get(k),r))throw Error('Conflicting targets in selected files for '+r.entity+' · '+r.period+'. Keep one version before uploading.');duplicates++;continue;}seen.set(k,r);if(map.has(k)){if(equal(map.get(k),r)){duplicates++;continue;}replaced++;}else added++;map.set(k,r);}return {rows:[...map.values()],added,replaced,duplicates};}
function templates(scope,cadence){let s=scopes[scope],heads=[cadence==='daily'?'Date':'Month',s.column,...(scope==='category'?['CategoryLevel']:[]),...metrics.map(k=>col[k])];return heads.join(',')+'\r\n';}
const signed=v=>v==null?'—':(v>0?'+':v<0?'−':'')+(Math.abs(v)*100).toFixed(1)+'%';
const band=v=>v==null?'neutral':v>=1?'achieved':v>=.8&&v<=.9?'watch':v>.9?'near':'behind';
return {scopes,metrics,col,key,equal,parse,merge,templates,signed,band};
})();

