moduleViews.sales.push('targets');moduleViews.workspace.splice(1,0,'targets');
biNames.business='Vertical (Business Unit)';
let targetPreviewState=null,targetUploadBusy=false,targetReportState=null,targetScope='kam',targetCadence='monthly',targetMetric='gmv',targetLevel='1',targetSearch='',targetSort='actual',targetDir=-1,targetPage=0;
function targetUploadPanel(){return panel('Daily & monthly target uploads','Eight upload options · GMV, GOS, NMV and NOS · Editable CSV templates',`<div class="target-upload-intro"><div><span class="modern-eyebrow">COMMERCIAL PLANNING</span><h3>Give every team a clear target.</h3><p>Upload daily or monthly plans at any level. Saved targets travel with your full HTML export and data backup.</p></div><button class="primary" id="openTargets">View target achievement ↗</button></div><div class="target-upload-grid">${Object.entries(TargetEngine.scopes).map(([k,s],i)=>`<article class="target-upload-card"><div class="target-upload-title"><span class="target-icon">${['◎','▤','◈','▥'][i]}</span><h3>${s.label} targets</h3><span class="target-count">${num((data.targets||[]).filter(r=>r.scope===k).length)} saved</span></div><p>${k==='vertical'?'Matches Business Unit in sales reports':k==='category'?'Supports Category 1 through Category 5':k==='seller'?'Matches Vendor / shop account names':'Matches Sales Person / KAM names'}</p>${['daily','monthly'].map(c=>`<div class="target-upload-option"><b>${c==='daily'?'Daily':'Monthly'}</b><div><button aria-label="Download ${s.label} ${c} target template" data-target-template="${k}|${c}">↓ Template</button><button class="target-upload-button" aria-label="Upload ${s.label} ${c} targets" data-target-upload="${k}|${c}">＋ Upload CSV</button></div></div>`).join('')}<button class="target-names" data-target-names="${k}">↓ Export matching names</button></article>`).join('')}</div><input id="targetFileInput" type="file" accept=".csv,text/csv" multiple hidden><div id="targetPreview"></div><details class="target-rules"><summary>Target upload rules & color guide</summary><p>Download a template, fill it in Excel, then save as CSV UTF-8. Names must match the sales reports exactly. Dates use YYYY-MM-DD; months use YYYY-MM. CategoryLevel is 1–5. Vertical uses Business Unit. Blanks mean no target, zero is an explicit zero target. At least one metric is required per row.</p><p>Identical target rows are skipped. A changed row replaces the same level, frequency, period and name after preview; other records stay saved. Conflicting rows in the same upload must be corrected before saving. Daily and monthly plans are independent and are never added together.</p><div class="target-legend"><span class="positive">+ Growth</span><span class="negative">− Decline</span><span class="attainment watch">80–90% achievement</span><span class="attainment near">Above 90%, below 100%</span><span class="attainment achieved">100%+ achieved</span></div></details>`);}
const originalDataPage=dataPage;dataPage=function(){return '<div class="data-shortcuts"><button id="jumpSales">Sales reports ↓</button><button id="jumpTargets">Planning targets ↓</button><span>Daily refresh & commercial plans</span></div>'+originalDataPage().replace('<div class="grid-equal">',targetUploadPanel()+'<div class="grid-equal">');};
function targetTemplate(scope,cadence){download('Othoba_'+TargetEngine.scopes[scope].label+'_'+cadence+'_Targets.csv','\uFEFF'+TargetEngine.templates(scope,cadence),'text/csv;charset=utf-8');}
let targetUploadChoice=null;
async function stageTargets(files){if(!files.length||targetUploadBusy)return;if(bulkBusy||bulkState)return toast('Finish or discard the sales import preview before uploading targets.');targetUploadBusy=true;try{let[scope,cadence]=targetUploadChoice;await backgroundTask('targetStart');for(let i=0;i<files.length;i++){setWorkStatus('Checking target file '+(i+1)+' / '+files.length+'…');await backgroundTask('targetFile',{file:files[i],scope,cadence});}targetPreviewState=await backgroundTask('targetPreview');drawTargetsPreview();}catch(e){toast(e.message);}finally{targetUploadBusy=false;setWorkStatus('');if($('#targetFileInput'))$('#targetFileInput').value='';}}
function drawTargetsPreview(){let p=targetPreviewState,box=$('#targetPreview');if(!p||!box)return;box.innerHTML=`<section class="target-preview"><h3>Target import preview</h3><div class="target-preview-summary"><span><b>${num(p.added)}</b> new rows</span><span><b>${num(p.replaced)}</b> replacements</span><span><b>${num(p.duplicates)}</b> duplicates skipped</span><span><b>${p.errors.length}</b> invalid files excluded</span></div>${p.conflict?'<p class="error">'+esc(p.conflict)+'</p>':''}${p.errors.map(e=>'<p class="error">'+esc(e.file)+': '+esc(e.error)+'</p>').join('')}<p class="thin">Replacements update all four target metrics on that row; blank cells clear the old target. Preview shows the first 50 rows.</p><div class="table-wrap"><table><thead><tr><th>Level</th><th>Period</th><th>Name</th><th>GMV target</th><th>GOS target</th><th>NMV target</th><th>NOS target</th></tr></thead><tbody>${p.rows.map(r=>`<tr><td>${esc(TargetEngine.scopes[r.scope].label)}${r.level?' '+r.level:''}</td><td>${esc(r.period)}</td><td>${esc(r.entity)}</td>${TargetEngine.metrics.map(k=>'<td>'+money(r[k])+'</td>').join('')}</tr>`).join('')}</tbody></table></div><div class="upload-controls"><button id="saveTargets" class="primary" ${p.conflict||!p.added&&!p.replaced?'disabled':''}>Save target records</button><button id="discardTargets">Discard target preview</button><span class="thin">Saved sales history stays unchanged.</span></div></section>`;$('#discardTargets').onclick=async()=>{await backgroundTask('targetDiscard');targetPreviewState=null;box.innerHTML='';};$('#saveTargets').onclick=saveTargets;enhanceTables(box);makeSearchableSelects(box);}
async function saveTargets(){if(targetUploadBusy)return;targetUploadBusy=true;$('#saveTargets').disabled=true;try{if(!db)throw Error('Browser storage is unavailable.');let next=await backgroundTask('targetCommit');await saveDB(next);await backgroundTask('targetAccept');data=Packed.state(next);targetPreviewState=null;persisted=true;queryResults.clear();updateSaved();await render();toast('Targets saved. Export full HTML to share them with all history.');}catch(e){toast('Target save failed: '+e.message);if($('#saveTargets'))$('#saveTargets').disabled=false;}finally{targetUploadBusy=false;}}
function targetsPage(){return panel('Targets & achievement','Independent scorecards for each level and planning frequency',`<div class="target-report-controls"><label>Level<select id="targetScope" data-search-label="Target level" aria-label="Target level">${Object.entries(TargetEngine.scopes).map(([k,s])=>`<option value="${k}" ${k===targetScope?'selected':''}>${s.label}</option>`).join('')}</select></label><label>Plan<select id="targetCadence" data-search-label="Target frequency" aria-label="Target frequency"><option value="daily" ${targetCadence==='daily'?'selected':''}>Daily targets</option><option value="monthly" ${targetCadence==='monthly'?'selected':''}>Monthly targets</option></select></label><label>Metric<select id="targetMetric" data-search-label="Target metric" aria-label="Target metric">${TargetEngine.metrics.map(k=>`<option value="${k}" ${k===targetMetric?'selected':''}>${k.toUpperCase()}</option>`).join('')}</select></label>${targetScope==='category'?'<label>Category level<select id="targetLevel" data-search-label="Target category level" aria-label="Target category level">'+[1,2,3,4,5].map(n=>'<option '+(targetLevel===String(n)?'selected':'')+'>'+n+'</option>').join('')+'</select></label>':''}<button id="manageTargets">Upload targets</button></div><p class="target-report-note">Uses the date range above and these planning controls. Global sales dimension filters do not apply here. Monthly actuals start on the first day of the selected start month and run through the selected end date; monthly targets remain full-month plans. Daily targets require every selected day.</p><div id="targetReportResult"><div class="loading">Preparing target scorecard…</div></div>`);}
async function loadTargetReport(){let ticket=++loadTargetReport.ticket;try{let r=await backgroundTask('targetReport',{scope:targetScope,cadence:targetCadence,metric:targetMetric,level:targetLevel,from,to});if(ticket!==loadTargetReport.ticket||currentView!=='targets')return;targetReportState=r;drawTargetReport();}catch(e){if($('#targetReportResult'))$('#targetReportResult').innerHTML='<p class="error">'+esc(e.message)+'</p>';}}loadTargetReport.ticket=0;
function targetReportRows(){let q=targetSearch.toLowerCase();return (targetReportState?.rows||[]).filter(r=>!q||(r.entity+' '+r.status).toLowerCase().includes(q)).sort((a,b)=>{let x=a[targetSort],y=b[targetSort];if(x==null)return y==null?0:1;if(y==null)return-1;return(typeof x==='number'?x-y:String(x).localeCompare(String(y)))*targetDir;});}
const targetHeaders=['Name','Target','Loaded actual','Achievement','Actual minus target','Target periods','Sales match','Status'];
function targetRecords(){return targetReportRows().map(r=>[r.entity,r.target??'',r.actual??'',r.attainment==null?'':pct(r.attainment),r.gap??'',r.targetHave+'/'+r.targetTotal,r.matched?'Matched':'No activity / unmatched',r.status]);}
async function exportTargetReport(copy=false){let rows=[targetHeaders,...targetRecords()];if(copy){try{await navigator.clipboard.writeText(rows.map(r=>r.join('\t')).join('\n'));toast('All matching target rows copied');}catch{toast('Clipboard unavailable. Use Export CSV.');}}else download('Othoba_'+targetScope+'_'+targetCadence+'_'+targetMetric+'_Achievement.csv','\uFEFF'+rows.map(r=>r.map(safeCSV).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function drawTargetReport(){let box=$('#targetReportResult'),r=targetReportState;if(!box||!r)return;let all=targetReportRows(),max=50;if(targetPage*max>=all.length)targetPage=0;let shown=all.slice(targetPage*max,(targetPage+1)*max),targeted=r.rows.filter(x=>x.target!==null),done=r.rows.filter(x=>x.attainment>=1).length;box.innerHTML=`<div class="target-report-stats"><div><span>Planning scope</span><b>${TargetEngine.scopes[targetScope].label} · ${targetMetric.toUpperCase()}</b><small>${formatDate(r.start)} – ${formatDate(r.end)}</small></div><div><span>Entities with plans</span><b>${num(targeted.length)}</b><small>${num(r.targetRows)} saved target rows in period</small></div><div><span>Target achieved</span><b>${num(done)}</b><small>100% or more with complete coverage</small></div><div><span>Sales report coverage</span><b>${r.have} / ${r.total} days</b><small>${r.have===r.total?'All required dates loaded':'Missing dates: achievement is unavailable'}</small></div></div><div class="target-legend"><span class="attainment achieved">100%+ achieved</span><span class="attainment near">Above 90%, below 100%</span><span class="attainment watch">80–90% watch</span><span class="attainment behind">Below 80%</span></div>${!(data.targets||[]).length?'<div class="notice">Upload targets in Data & daily uploads to begin. Sales activity is shown below so you can see the names to use in your templates.</div>':''}<div class="target-table-tools"><input id="targetSearch" type="search" placeholder="Search name or status…" aria-label="Search target report" value="${esc(targetSearch)}"><div><button id="targetCopy">Copy all rows</button><button id="targetExport">Export CSV</button><select id="targetSort" aria-label="Target sort column">${[['actual','Loaded actual'],['target','Target'],['attainment','Achievement'],['gap','Actual minus target'],['entity','Name']].map(([k,v])=>`<option value="${k}" ${targetSort===k?'selected':''}>${v}</option>`).join('')}</select><button id="targetDesc">↓ High to low</button><button id="targetAsc">↑ Low to high</button></div></div><div class="table-wrap"><table class="target-scorecard"><thead><tr>${targetHeaders.map((h,i)=>`<th ${i<5?'data-target-sort="'+['entity','target','actual','attainment','gap'][i]+'" tabindex="0"':''}>${h}${i===1||i===2?' · '+targetMetric.toUpperCase():''}</th>`).join('')}</tr></thead><tbody>${shown.map(x=>`<tr><td class="label">${esc(x.entity)}</td><td>${money(x.target)}</td><td>${money(x.actual)}</td><td><span class="attainment ${TargetEngine.band(x.attainment)}">${pct(x.attainment)}</span></td><td class="${x.gap>0?'positive':x.gap<0?'negative':''}">${x.gap==null?'—':(x.gap>0?'+':x.gap<0?'−':'')+money(Math.abs(x.gap))}</td><td>${x.targetHave} / ${x.targetTotal}</td><td>${x.matched?'Matched':'No activity / unmatched'}</td><td>${esc(x.status)}</td></tr>`).join('')||'<tr><td colspan="8">No targets or sales activity in this selection.</td></tr>'}</tbody></table></div><div class="table-bottom"><span>${num(all.length)} matching entities · ${targetCadence==='monthly'?'Full monthly targets; actuals through cutoff':'Independent daily plans'} · Blank targets are unknown; zero targets have no achievement percentage.</span><div class="pagination"><button id="targetPrev" ${!targetPage?'disabled':''}>Previous</button><span>${targetPage+1} / ${Math.max(1,Math.ceil(all.length/max))}</span><button id="targetNext" ${(targetPage+1)*max>=all.length?'disabled':''}>Next</button></div></div>`;$('#targetSearch').oninput=e=>{targetSearch=e.target.value;targetPage=0;let focus=e.target.selectionStart;drawTargetReport();$('#targetSearch').focus();$('#targetSearch').setSelectionRange(focus,focus);};$('#targetCopy').onclick=()=>exportTargetReport(true);$('#targetExport').onclick=()=>exportTargetReport();for(let[id,dir]of [['targetDesc',-1],['targetAsc',1]])$('#'+id).onclick=()=>{targetSort=$('#targetSort').value;targetDir=dir;targetPage=0;drawTargetReport();};$$('[data-target-sort]').forEach(el=>{el.onclick=()=>{let k=el.dataset.targetSort;targetDir=targetSort===k?-targetDir:-1;targetSort=k;drawTargetReport();};el.onkeydown=e=>{if(e.key==='Enter')el.click();};});$('#targetPrev').onclick=()=>{targetPage--;drawTargetReport();};$('#targetNext').onclick=()=>{targetPage++;drawTargetReport();};makeSearchableSelects(box);}
function bindContent(){salesBindContent();document.body.classList.toggle('target-view',currentView==='targets');if(currentView==='data'){$('#jumpSales').onclick=()=>$('#dropZone').scrollIntoView({behavior:'smooth',block:'center'});$('#jumpTargets').onclick=()=>$('#openTargets').scrollIntoView({behavior:'smooth',block:'center'});$$('[data-target-names]').forEach(b=>b.onclick=()=>targetNameReference(b.dataset.targetNames));$$('[data-target-template]').forEach(b=>b.onclick=()=>targetTemplate(...b.dataset.targetTemplate.split('|')));$$('[data-target-upload]').forEach(b=>b.onclick=()=>{if(targetUploadBusy||bulkBusy)return toast('Wait for the current upload to finish.');targetUploadChoice=b.dataset.targetUpload.split('|');$('#targetFileInput').click();});$('#targetFileInput').onchange=e=>stageTargets([...e.target.files]);$('#openTargets').onclick=()=>nav('targets');drawTargetsPreview();}if(currentView==='targets'){for(let[id,name]of [['targetScope','scope'],['targetCadence','cadence'],['targetMetric','metric'],['targetLevel','level']])if($('#'+id))$('#'+id).onchange=e=>{if(name==='scope')targetScope=e.target.value;if(name==='cadence')targetCadence=e.target.value;if(name==='metric')targetMetric=e.target.value;if(name==='level')targetLevel=e.target.value;targetPage=0;targetSearch='';render();};$('#manageTargets').onclick=()=>nav('data');loadTargetReport();}makeSearchableSelects(document);}

const salesStageFiles=stageFiles;stageFiles=async function(files){if(targetUploadBusy||targetPreviewState)return toast("Save or discard the target preview before uploading sales reports.");return salesStageFiles(files);};
const salesExportView=exportView;exportView=function(){if(currentView==='targets')return exportTargetReport();return salesExportView();};

const salesOverview=biOverview;biOverview=function(mtd=false){return salesOverview(mtd)+'<div class="planning-link"><div><strong>Targets & achievement</strong><p>'+num((data.targets||[]).length)+' saved plans across KAM, seller, category and vertical levels.</p></div><button data-nav="targets">Open target scorecard ↗</button></div>';};

function targetNameReference(scope){let s=TargetEngine.scopes[scope],rows=[[s.column,...(scope==='category'?['CategoryLevel']:[])]];if(scope==='category'){for(let level=1;level<=5;level++)for(let name of data.store.options('cat'+level))if(name!=='Unmapped')rows.push([name,level]);}else for(let name of data.store.options(s.field))if(name!=='Unmapped')rows.push([name]);download('Othoba_'+s.label+'_Matching_Names.csv','\uFEFF'+rows.map(r=>r.map(safeCSV).join(',')).join('\r\n'),'text/csv;charset=utf-8');}

targetPanel=function(){return `<section class="target-box"><h2>Portfolio targets & achievement</h2><p>Upload and review independent daily or monthly plans by KAM, seller, category and vertical. ${num((data.targets||[]).length)} target rows saved.</p><button data-nav="targets" class="primary">Open target scorecard ↗</button></section>`;};

function cleanToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dhaka',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
const populatedApplyPeriod=applyPeriod;applyPeriod=function(p){if(!data.store.dates.length){from=to=cleanToday();$('#from').value=from;$('#to').value=to;currentView='data';buildFilters();page=0;return render();}return populatedApplyPeriod(p);};
const populatedDataPage=dataPage;dataPage=function(){return (!data.rows.length?'<section class="planning-link"><div><strong>Your clean workspace is ready</strong><p>No preloaded sales, targets or previous import records. Choose all your daily CSV files together below. Identical copies are skipped; different reports for one date can be reviewed before saving.</p></div></section>':'')+populatedDataPage();};

